class BigNumCalculator:
    """
    This class implements basic arithmetic operations for arbitrarily large integers
    represented as strings.  It supports addition, subtraction and multiplication
    of numbers that may contain a leading minus sign.
    """

    @staticmethod
    def _strip_leading_zeros(s: str) -> str:
        """Remove leading zeros; return '0' if the string becomes empty."""
        s = s.lstrip("0")
        return s if s else "0"

    @staticmethod
    def _parse_number(s: str) -> tuple[str, str]:
        """Return sign ('+' or '-') and the absolute value with no leading zeros."""
        if not s:
            raise ValueError("Empty string is not a valid number")
        sign = "-" if s[0] == "-" else "+"
        abs_val = BigNumCalculator._strip_leading_zeros(s[1:] if sign == "-" else s)
        return sign, abs_val

    @staticmethod
    def _compare_abs(a: str, b: str) -> int:
        """Compare absolute values of two positive number strings.
        Return 1 if a > b, -1 if a < b, 0 if equal."""
        if len(a) != len(b):
            return 1 if len(a) > len(b) else -1
        if a == b:
            return 0
        return 1 if a > b else -1

    @staticmethod
    def _add_abs(a: str, b: str) -> str:
        """Add two positive integer strings and return the result as a string."""
        i, j = len(a) - 1, len(b) - 1
        carry, res = 0, []
        while i >= 0 or j >= 0 or carry:
            x = int(a[i]) if i >= 0 else 0
            y = int(b[j]) if j >= 0 else 0
            total = x + y + carry
            res.append(str(total % 10))
            carry = total // 10
            i -= 1
            j -= 1
        return "".join(reversed(res))

    @staticmethod
    def _subtract_abs(a: str, b: str) -> str:
        """Assumes a >= b (both positive).  Return a - b as a string."""
        i, j = len(a) - 1, len(b) - 1
        borrow, res = 0, []
        while i >= 0:
            x = int(a[i]) - borrow
            y = int(b[j]) if j >= 0 else 0
            if x < y:
                x += 10
                borrow = 1
            else:
                borrow = 0
            res.append(str(x - y))
            i -= 1
            j -= 1
        return BigNumCalculator._strip_leading_zeros("".join(reversed(res)))

    @staticmethod
    def _multiply_abs(a: str, b: str) -> str:
        """Multiply two positive integer strings."""
        if a == "0" or b == "0":
            return "0"
        n, m = len(a), len(b)
        result = [0] * (n + m)
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                mul = int(a[i]) * int(b[j])
                pos = i + j + 1
                total = result[pos] + mul
                result[pos] = total % 10
                result[pos - 1] += total // 10
        # Convert to string and strip leading zeros
        result_str = "".join(map(str, result)).lstrip("0")
        return result_str if result_str else "0"

    @staticmethod
    def add(num1: str, num2: str) -> str:
        """
        Adds two big numbers.
        :param num1: The first number to add, str.
        :param num2: The second number to add, str.
        :return: The sum of the two numbers, str.
        """
        sign1, a = BigNumCalculator._parse_number(num1)
        sign2, b = BigNumCalculator._parse_number(num2)

        if sign1 == sign2:
            sum_abs = BigNumCalculator._add_abs(a, b)
            if sign1 == "-" and sum_abs != "0":
                return "-" + sum_abs
            return sum_abs
        else:
            cmp = BigNumCalculator._compare_abs(a, b)
            if cmp == 0:
                return "0"
            elif cmp > 0:
                diff = BigNumCalculator._subtract_abs(a, b)
                return ("-" + diff) if sign1 == "-" else diff
            else:
                diff = BigNumCalculator._subtract_abs(b, a)
                return ("-" + diff) if sign2 == "-" else diff

    @staticmethod
    def subtract(num1: str, num2: str) -> str:
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract, str.
        :param num2: The second number to subtract, str.
        :return: The difference of the two numbers, str.
        """
        # Subtraction is addition with the second number negated.
        sign2, b = BigNumCalculator._parse_number(num2)
        negated_num2 = ("-" if sign2 == "+" else "") + (b if sign2 == "+" else b)
        return BigNumCalculator.add(num1, negated_num2)

    @staticmethod
    def multiply(num1: str, num2: str) -> str:
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply, str.
        :param num2: The second number to multiply, str.
        :return: The product of the two numbers, str.
        """
        sign1, a = BigNumCalculator._parse_number(num1)
        sign2, b = BigNumCalculator._parse_number(num2)

        if a == "0" or b == "0":
            return "0"

        product = BigNumCalculator._multiply_abs(a, b)
        if sign1 == "-" and sign2 == "-":
            return product
        if sign1 == "-" or sign2 == "-":
            return "-" + product
        return product
