from __future__ import annotations
from typing import List, Tuple, Optional


class EightPuzzle:
    """
    Implementation of the classic 8‑puzzle game.
    """

    def __init__(self, initial_state: List[List[int]]) -> None:
        """
        :param initial_state: a 3x3 list of integers representing the starting board
        """
        self.initial_state = [row[:] for row in initial_state]
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    @staticmethod
    def _state_to_tuple(state: List[List[int]]) -> Tuple[Tuple[int, ...], ...]:
        """Convert a list-of-lists board to an immutable tuple for hashing."""
        return tuple(tuple(row) for row in state)

    def find_blank(self, state: List[List[int]]) -> Tuple[int, int]:
        """
        Find the position of the blank (0) tile.
        """
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return i, j
        raise ValueError("No blank tile found in the state")

    def move(self, state: List[List[int]], direction: str) -> List[List[int]]:
        """
        Return a new state after moving the blank tile in the specified direction.
        """
        i, j = self.find_blank(state)
        new_state = [row[:] for row in state]

        if direction == "up":
            new_state[i][j], new_state[i - 1][j] = new_state[i - 1][j], new_state[i][j]
        elif direction == "down":
            new_state[i][j], new_state[i + 1][j] = new_state[i + 1][j], new_state[i][j]
        elif direction == "left":
            new_state[i][j], new_state[i][j - 1] = new_state[i][j - 1], new_state[i][j]
        elif direction == "right":
            new_state[i][j], new_state[i][j + 1] = new_state[i][j + 1], new_state[i][j]
        else:
            raise ValueError(f"Invalid move direction: {direction}")

        return new_state

    def get_possible_moves(self, state: List[List[int]]) -> List[str]:
        """
        Return all legal moves from the given state.
        """
        moves = []
        i, j = self.find_blank(state)
        if i > 0:
            moves.append("up")
        if i < 2:
            moves.append("down")
        if j > 0:
            moves.append("left")
        if j < 2:
            moves.append("right")
        return moves

    def solve(self) -> Optional[List[str]]:
        """
        Breadth‑first search for a solution from the initial state to the goal state.
        Returns a list of moves or None if unsolvable.
        """
        start_tuple = self._state_to_tuple(self.initial_state)
        goal_tuple = self._state_to_tuple(self.goal_state)

        if start_tuple == goal_tuple:
            return []

        open_list: List[Tuple[List[List[int]], List[str]]] = [
            (self.initial_state, [])
        ]
        closed_set: set[Tuple[Tuple[int, ...], ...]] = {start_tuple}

        while open_list:
            current_state, path = open_list.pop(0)
            current_tuple = self._state_to_tuple(current_state)

            if current_tuple == goal_tuple:
                return path

            for move_dir in self.get_possible_moves(current_state):
                new_state = self.move(current_state, move_dir)
                new_tuple = self._state_to_tuple(new_state)

                if new_tuple not in closed_set:
                    closed_set.add(new_tuple)
                    open_list.append((new_state, path + [move_dir]))

        return None
