        Returns a list of moves or None if unsolvable.
        """
        start_tuple = self._state_to_tuple(self.initial_state)
        goal_tuple = self._state_to_tuple(self.goal_state)

        if start_tuple == goal_tuple:
            return []

        open_list: List[Tuple[List[List[int]], List[str]]] = [
            (self.initial_state, [])
        ]
        closed_set: set[Tuple[Tuple[int, ...], ...]] = {start_tuple}

        while open_list:
            current_state, path = open_list.pop(0)
            current_tuple = self._state_to_tuple(current_state)

            if current_tuple == goal_tuple:
                return path

            for move_dir in self.get_possible_moves(current_state):
                new_state = self.move(current_state, move_dir)
                new_tuple = self._state_to_tuple(new_state)

                if new_tuple not in closed_set:
                    closed_set.add(new_tuple)
                    open_list.append((new_state, path + [move_dir]))

        return None

