        job = {
            'job_title': job_title,
            'company': company,
            'requirements': requirements
        }
        self.job_listings.append(job)

    def remove_job(self, job):
        """Remove a job listing."""
        self.job_listings.remove(job)

    def submit_resume(self, name, skills, experience):
        """Submit a new resume."""
        resume = {
            'name': name,
            'skills': skills,
            'experience': experience
        }
        self.resumes.append(resume)

    def withdraw_resume(self, resume):
        """Withdraw a submitted resume."""
        self.resumes.remove(resume)

    def search_jobs(self, criteria):
        """Search job listings that match the given criteria."""
        matching_jobs = []
        for job_listing in self.job_listings:
            title_match = criteria.lower() in job_listing['job_title'].lower()
            requirements_match = any(
                criteria.lower() == r.lower() for r in job_listing['requirements']
            )
            if title_match or requirements_match:
                matching_jobs.append(job_listing)
        return matching_jobs

    def get_job_applicants(self, job):
        """Get resumes that satisfy the job's requirements."""
        applicants = []
        for resume in self.resumes:
            if self.matches_requirements(resume, job['requirements']):
                applicants.append(resume)
        return applicants

    @staticmethod
    def matches_requirements(resume, requirements):
        """Return True if all resume skills are present in the job requirements."""
        # All skills in the resume must be in the job requirements
        for skill in resume.get('skills', []):
            if skill not in requirements:
                return False
        return True

import numpy as np


class MetricsCalculator2:
    """
    The class provides methods to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP)
    based on input data. MRR measures the ranking quality, while MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        Compute the MRR of the input data. MRR is the mean of reciprocal ranks.

        Parameters
        ----------
        data : tuple or list
            The data must be a tuple (actual_result, ground_truth_num),
            where actual_result is a list/tuple of 0s and 1s and
            ground_truth_num is the total number of relevant items.
            It can also be a list of such tuples.

        Returns
        -------
        tuple
            (mrr_value, list_of_mrr_per_item)

        Examples
        --------
        >>> MetricsCalculator2.mrr(([1, 0, 1, 0], 4))
        (1.0, [1.0])
        >>> MetricsCalculator2.mrr([([1, 0, 1, 0], 4), ([0, 1, 0, 1], 4)])
        (0.75, [1.0, 0.5])
        """
        if type(data) not in (list, tuple):
            raise Exception('the input must be a tuple([0,...,1,...],int) or an iterable of list of tuple')

        if len(data) == 0:
            return (0.0, [0.0])

        # Single query
        if isinstance(data, tuple):
            sub_list, total_num = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return (0.0, [0.0])
            ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
            mr_np = sub_list * ranking_array
            mr = 0.0
            for val in mr_np:
                if val > 0:
                    mr = val
                    break
            return (mr, [mr])

        # Multiple queries
        separate_result = []
        for sub_list, total_num in data:
            sub_list = np.array(sub_list)
            if total_num == 0:
                mr = 0.0
            else:
                ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
                mr_np = sub_list * ranking_array
                mr = 0.0
                for val in mr_np:
                    if val > 0:
                        mr = val
                        break
            separate_result.append(mr)
        return (np.mean(separate_result), separate_result)

    @staticmethod
    def map(data):
        """
        Compute the MAP of the input data. MAP is the mean of average precisions.

        Parameters
        ----------
        data : tuple or list
            The data must be a tuple (actual_result, ground_truth_num),
            where actual_result is a list/tuple of 0s and 1s and
            ground_truth_num is the total number of relevant items.
            It can also be a list of such tuples.

        Returns
        -------
        tuple
            (map_value, list_of_ap_per_item)

        Examples
        --------
        >>> MetricsCalculator2.map(([1, 0, 1, 0], 4))
        (0.41666666666666663, [0.41666666666666663])
        >>> MetricsCalculator2.map([([1, 0, 1, 0], 4), ([0, 1, 0, 1], 4)])
        (0.3333333333333333, [0.41666666666666663, 0.25])
        """
        if type(data) not in (list, tuple):
            raise Exception('the input must be a tuple([0,...,1,...],int) or an iterable of list of tuple')

        if len(data) == 0:
            return (0.0, [0.0])

        # Single query
        if isinstance(data, tuple):
            sub_list, total_num = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return (0.0, [0.0])
            ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
            right_ranking_list = []
            count = 1
            for t in sub_list:
                if t == 0:
                    right_ranking_list.append(0)
                else:
                    right_ranking_list.append(count)
                    count += 1
            ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num
            return (ap, [ap])

        # Multiple queries
        separate_result = []
        for sub_list, total_num in data:
            sub_list = np.array(sub_list)
            if total_num == 0:
                ap = 0.0
            else:
                ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
                right_ranking_list = []
                count = 1
                for t in sub_list:
                    if t == 0:
                        right_ranking_list.append(0)
                    else:
                        right_ranking_list.append(count)
                        count += 1
                ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num
            separate_result.append(ap)
        return (np.mean(separate_result), separate_result)

import numpy as np
from typing import Iterable, List, Tuple, Union


class MetricsCalculator2:
    """
    The class provides methods to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP)
    based on input data. MRR measures the ranking quality, while MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def _validate_item(item: Iterable[int]) -> np.ndarray:
        """Validate that the item is a list/tuple of 0/1 and return it as a numpy array."""
        arr = np.asarray(item)
        if arr.ndim != 1:
            raise ValueError("Item must be a one‑dimensional list of 0/1.")
        if not np.all(np.isin(arr, [0, 1])):
            raise ValueError("Item must contain only 0 or 1.")
        return arr

    @staticmethod
    def _mrr_single(sub_list: Iterable[int], total_num: int) -> Tuple[float, List[float]]:
        """Compute MRR for a single query."""
        if total_num == 0:
            return 0.0, [0.0]
        arr = MetricsCalculator2._validate_item(sub_list)
        if arr.size == 0:
            return 0.0, [0.0]
        # reciprocal of rank of first relevant item
        indices = np.where(arr == 1)[0]
        if indices.size == 0:
            return 0.0, [0.0]
        rank = indices[0] + 1
        return 1.0 / rank, [1.0 / rank]

    @staticmethod
    def _map_single(sub_list: Iterable[int], total_num: int) -> Tuple[float, List[float]]:
        """Compute MAP for a single query."""
        if total_num == 0:
            return 0.0, [0.0]
        arr = MetricsCalculator2._validate_item(sub_list)
        if arr.size == 0:
            return 0.0, [0.0]
        ranking_array = 1.0 / (np.arange(arr.size) + 1)
        # ranks of relevant items (1‑based)
        ranks = np.arange(arr.size) + 1
        # precision at each rank is simply the rank for relevant items
        relevant_ranks = np.where(arr == 1, ranks, 0)
        ap = (relevant_ranks * ranking_array).sum() / total_num
        return ap, [ap]

    @staticmethod
    def mrr(data: Union[Tuple[Iterable[int], int], List[Tuple[Iterable[int], int]]]) -> Tuple[float, List[float]]:
        """
        Compute Mean Reciprocal Rank (MRR).

        Parameters
        ----------
        data : tuple or list of tuples
            Each element is a tuple of (list of 0/1, total number of ground truth items).
            If `data` is a single tuple, a single MRR value is returned.
            If `data` is a list, the mean MRR over all tuples is returned.

        Returns
        -------
        tuple
            (overall MRR, list of individual MRR values).
        """
        if isinstance(data, tuple):
            if len(data) != 2:
                raise ValueError("Tuple input must be of the form (list_of_0/1, total_num).")
            return MetricsCalculator2._mrr_single(data[0], data[1])

        if isinstance(data, list):
            if len(data) == 0:
                return 0.0, [0.0]
            results = []
            for item in data:
                if not (isinstance(item, tuple) and len(item) == 2):
                    raise ValueError("Each element in the list must be a tuple (list_of_0/1, total_num).")
                mr, _ = MetricsCalculator2._mrr_single(item[0], item[1])
                results.append(mr)
            mean_mr = float(np.mean(results)) if results else 0.0
            return mean_mr, results

        raise TypeError("Input must be a tuple or a list of tuples.")

    @staticmethod
    def map(data: Union[Tuple[Iterable[int], int], List[Tuple[Iterable[int], int]]]) -> Tuple[float, List[float]]:
        """
        Compute Mean Average Precision (MAP).

        Parameters
        ----------
        data : tuple or list of tuples
            Each element is a tuple of (list of 0/1, total number of ground truth items).
            If `data` is a single tuple, a single MAP value is returned.
            If `data` is a list, the mean MAP over all tuples is returned.

        Returns
        -------
        tuple
            (overall MAP, list of individual MAP values).
        """
        if isinstance(data, tuple):
            if len(data) != 2:
                raise ValueError("Tuple input must be of the form (list_of_0/1, total_num).")
            return MetricsCalculator2._map_single(data[0], data[1])

        if isinstance(data, list):
            if len(data) == 0:
                return 0.0, [0.0]
            results = []
            for item in data:
                if not (isinstance(item, tuple) and len(item) == 2):
                    raise ValueError("Each element in the list must be a tuple (list_of_0/1, total_num).")
                ap, _ = MetricsCalculator2._map_single(item[0], item[1])
                results.append(ap)
            mean_ap = float(np.mean(results)) if results else 0.0
            return mean_ap, results

        raise TypeError("Input must be a tuple or a list of tuples.")

