import re

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    # Compile a regex once for performance.  The pattern matches
    # decimal (e.g., &#65;) and hexadecimal (e.g., &#x41;) numeric
    # character references.  The `re.IGNORECASE` flag allows both
    # lower- and upper‑case 'x' in the hexadecimal form.
    _entity_pattern = re.compile(r'&#(x?[0-9a-fA-F]+);', re.IGNORECASE)

    def __init__(self):
        pass

    def replace(self, string: str) -> str:
        """
        Replaces numeric character references (HTML entities) in the input string
        with their corresponding Unicode characters.

        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        """
        if not string:
            return string

        def _replace_match(match: re.Match) -> str:
            value = match.group(1)
            try:
                if value.lower().startswith('x'):  # hexadecimal
                    code_point = int(value[1:], 16)
                else:  # decimal
                    code_point = int(value, 10)
                # For code points outside Unicode range, chr() raises ValueError.
                return chr(code_point)
            except (ValueError, OverflowError):
                # If conversion fails, return the original entity unchanged.
                return match.group(0)

        return self._entity_pattern.sub(_replace_match, string)

    @staticmethod
    def is_hex_char(char: str) -> bool:
        """
        Determines whether a given character is a hexadecimal digit.

        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        """
        if len(char) != 1:
            return False
        return char.isdigit() or ('a' <= char.lower() <= 'f')
