import math

class Statistics3:
    """
    This class provides static methods for common statistical calculations.
    """

    @staticmethod
    def median(data):
        """Return the median of the list `data`."""
        if not data:
            return None
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 1:
            return sorted_data[mid]
        return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0

    @staticmethod
    def mode(data):
        """Return a list containing the mode(s) of the list `data`."""
        if not data:
            return []
        counts = {}
        for value in data:
            counts[value] = counts.get(value, 0) + 1
        max_count = max(counts.values())
        return [value for value, count in counts.items() if count == max_count]

    @staticmethod
    def correlation(x, y):
        """Return Pearson correlation coefficient between two lists `x` and `y`."""
        if len(x) != len(y) or not x:
            return None
        n = len(x)
        mean_x = sum(x) / n
        mean_y = sum(y) / n
        num = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
        den_sq = sum((xi - mean_x) ** 2 for xi in x) * sum((yi - mean_y) ** 2 for yi in y)
        if den_sq == 0:
            return None
        return num / math.sqrt(den_sq)

    @staticmethod
    def mean(data):
        """Return the mean of the list `data`."""
        if not data:
            return None
        return sum(data) / len(data)

    @staticmethod
    def correlation_matrix(data):
        """
        Return a correlation matrix for a 2D list `data`
        where each sublist represents a row of observations.
        """
        if not data or not data[0]:
            return []
        ncols = len(data[0])
        matrix = [[None] * ncols for _ in range(ncols)]
        for i in range(ncols):
            col_i = [row[i] for row in data]
            for j in range(ncols):
                col_j = [row[j] for row in data]
                matrix[i][j] = Statistics3.correlation(col_i, col_j)
        return matrix

    @staticmethod
