import math
from collections import Counter
from typing import List, Iterable


class Statistics3:
    """
    This is a class that implements methods for calculating indicators such as median, mode,
    correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def median(data: Iterable[float]) -> float:
        """
        calculates the median of the given list.
        """
        if not data:
            raise ValueError("median requires at least one data point")

        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0
        return float(sorted_data[mid])

    @staticmethod
    def mode(data: Iterable[float]) -> List[float]:
        """
        calculates the mode of the given list.
        """
        if not data:
            raise ValueError("mode requires at least one data point")

        counts = Counter(data)
        max_count = max(counts.values())
        if max_count == 1:
            return []  # No mode
        return sorted([value for value, cnt in counts.items() if cnt == max_count])

    @staticmethod
    def mean(data: Iterable[float]) -> float:
        """
        calculates the mean of the given list.
        """
        if not data:
            raise ValueError("mean requires at least one data point")

        return sum(data) / len(data)

    @staticmethod
    def standard_deviation(data: Iterable[float]) -> float:
        """
        calculates the standard deviation of the given list.
        Uses sample standard deviation (n-1 in denominator).
        """
        data = list(data)
        n = len(data)
        if n < 2:
            raise ValueError("standard_deviation requires at least two data points")

        mean_val = Statistics3.mean(data)
        variance = sum((x - mean_val) ** 2 for x in data) / (n - 1)
        return math.sqrt(variance)

    @staticmethod
    def z_score(data: Iterable[float]) -> List[float]:
        """
        calculates the z-score of the given list.
        """
        data = list(data)
        n = len(data)
        if n < 2:
            raise ValueError("z_score requires at least two data points")

        mean_val = Statistics3.mean(data)
        std_val = Statistics3.standard_deviation(data)
        if std_val == 0:
            # Avoid division by zero; return zeros
            return [0.0 for _ in data]
        return [(x - mean_val) / std_val for x in data]

    @staticmethod
    def correlation(x: Iterable[float], y: Iterable[float]) -> float:
        """
        calculates the correlation of the given list.
        """
        x = list(x)
        y = list(y)
        n = len(x)
        if n != len(y):
            raise ValueError("x and y must have the same length")
        if n < 2:
            raise ValueError("correlation requires at least two data points")

        mean_x = Statistics3.mean(x)
        mean_y = Statistics3.mean(y)
        std_x = Statistics3.standard_deviation(x)
        std_y = Statistics3.standard_deviation(y)

        if std_x == 0 or std_y == 0:
            return 0.0

        cov = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n)) / (n - 1)
        return cov / (std_x * std_y)

    @staticmethod
    def correlation_matrix(data: Iterable[Iterable[float]]) -> List[List[float]]:
        """
        calculates the correlation matrix of the given list.
        Each inner list is treated as a variable.
        """
        variables = [list(v) for v in data]
        if not variables:
            raise ValueError("correlation_matrix requires at least one variable")
        n_vars = len(variables)
        # Validate lengths
        length = len(variables[0])
        for v in variables:
            if len(v) != length:
                raise ValueError("All variables must have the same number of observations")

        matrix = [[0.0] * n_vars for _ in range(n_vars)]
        for i in range(n_vars):
            for j in range(i, n_vars):
                corr = Statistics3.correlation(variables[i], variables[j])
                matrix[i][j] = corr
                matrix[j][i] = corr
        return matrix
