class Calculator:
    """
    This is a class for a calculator, capable of performing basic arithmetic calculations
    on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    """

    def __init__(self):
        """
        Initialize the operations performed by the five operators '+', '-', '*', '/', '^'
        """
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y,
        }

    def calculate(self, expression):
        """
        Calculate the value of a given expression.
        Supports parentheses, decimal numbers and the operators +, -, *, /, ^.
        Returns None if the expression is empty or cannot be evaluated.
        """
        if not expression:
            return None

        operand_stack = []
        operator_stack = []
        num_buffer = ""

        for char in expression:
            if char.isspace():
                # ignore whitespace
                continue

            if char.isdigit() or char == ".":
                num_buffer += char
                continue

            # Flush the number buffer to operand stack
            if num_buffer:
                operand_stack.append(float(num_buffer))
                num_buffer = ""

            if char in self.operators:
                # Apply operators with higher or equal precedence
                while (
                    operator_stack
                    and operator_stack[-1] != "("
                    and self.precedence(operator_stack[-1]) >= self.precedence(char)
                ):
                    operand_stack, operator_stack = self.apply_operator(
                        operand_stack, operator_stack
                    )
                operator_stack.append(char)
            elif char == "(":
                operator_stack.append(char)
            elif char == ")":
                # Pop until matching '('
                while operator_stack and operator_stack[-1] != "(":
                    operand_stack, operator_stack = self.apply_operator(
                        operand_stack, operator_stack
                    )
                if not operator_stack:
                    # Mismatched parentheses
                    return None
                operator_stack.pop()  # Remove '('
            else:
                # Invalid character
                return None

        # Flush remaining number
        if num_buffer:
            operand_stack.append(float(num_buffer))

        # Process remaining operators
        while operator_stack:
            if operator_stack[-1] == "(" or operator_stack[-1] == ")":
                # Unmatched parentheses
                return None
            operand_stack, operator_stack = self.apply_operator(
                operand_stack, operator_stack
            )

        return operand_stack[-1] if operand_stack else None

    def precedence(self, operator):
        """
        Returns the priority of the specified operator.
        Higher number means higher precedence.
        """
        precedences = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
        return precedences.get(operator, 0)

    def apply_operator(self, operand_stack, operator_stack):
        """
        Use the operator at the top of the operator stack to perform the operation
        on the two numbers at the top of the operand stack.
        """
        if not operator_stack:
            return operand_stack, operator_stack

        operator = operator_stack.pop()

        if operator not in self.operators:
            return operand_stack, operator_stack

        # Pop operands in correct order
        try:
            operand2 = operand_stack.pop()
            operand1 = operand_stack.pop()
        except IndexError:
            # Not enough operands
            return operand_stack, operator_stack

        try:
            result = self.operators[operator](operand1, operand2)
        except ZeroDivisionError:
            # Division by zero; treat as error
            result = None

        operand_stack.append(result)
        return operand_stack, operator_stack

