class JobMarketplace:
    """
    This class provides functionalities to publish positions, remove positions,
    submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    """

    def __init__(self):
        self.job_listings = []
        self.resumes = []

    def post_job(self, job_title, company, requirements):
        """
        Publish a new job posting and add it to the job_listings list.
        """
        job = {
            'job_title': job_title,
            'company': company,
            'requirements': requirements
        }
        self.job_listings.append(job)

    def remove_job(self, job):
        """
        Remove a job posting from the job_listings list.
        """
        try:
            self.job_listings.remove(job)
        except ValueError:
            pass  # ignore if job not found

    def submit_resume(self, name, skills, experience):
        """
        Submit a new resume and add it to the resumes list.
        """
        resume = {
            'name': name,
            'skills': skills,
            'experience': experience
        }
        self.resumes.append(resume)

    def withdraw_resume(self, resume):
        """
        Withdraw a resume from the resumes list.
        """
        try:
            self.resumes.remove(resume)
        except ValueError:
            pass  # ignore if resume not found

    def search_jobs(self, criteria):
        """
        Search for jobs whose requirements include the given criteria.
        """
        if not isinstance(criteria, str):
            return []

        matching_jobs = [
            job for job in self.job_listings
            if criteria in job.get('requirements', [])
        ]
        return matching_jobs

    def get_job_applicants(self, job):
        """
        Return a list of resumes that satisfy all of the job's requirements.
        """
        matching_resumes = [
            resume for resume in self.resumes
            if self.matches_requirements(job, resume)
        ]
        return matching_resumes

    @staticmethod
    def matches_requirements(job, resume):
        """
        Helper method to determine if a resume's skills satisfy a job's requirements.
        """
        job_requirements = set(job.get('requirements', []))
        resume_skills = set(resume.get('skills', []))
        return job_requirements.issubset(resume_skills)
