import numpy as np


class MetricsCalculator2:
    """
    The class provides methods to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP)
    based on input data. MRR measures ranking quality, while MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        Compute the MRR of the input data. MRR is the mean of reciprocal ranks.

        Parameters
        ----------
        data : tuple or list
            The data must be a tuple of the form ([0, 1, ...], ground_truth_num) or a list of such tuples.
            1 indicates a correct answer and 0 indicates an incorrect one.

        Returns
        -------
        tuple
            If `data` is a single tuple, returns (mrr, [mrr]).
            If `data` is a list of tuples, returns (mean_mrr, [mrr_1, mrr_2, ...]).
        """
        if type(data) != list and type(data) != tuple:
            raise Exception('the input must be a tuple([0,...,1,...],int) or an iterable of list of tuple')
        if len(data) == 0:
            return (0.0, [0.0])
        if type(data) == tuple:
            sub_list, total_num = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return (0.0, [0.0])
            else:
                ranking_array = 1.0 / (np.array(list(range(len(sub_list)))) + 1)
                mr_np = sub_list * ranking_array
                mr = 0.0
                for team in mr_np:
                    if team > 0:
                        mr = team
                        break
                return (mr, [mr])
        if type(data) == list:
            separate_result = []
            for sub_list, total_num in data:
                sub_list = np.array(sub_list)
                if total_num == 0:
                    mr = 0.0
                else:
                    ranking_array = 1.0 / (np.array(list(range(len(sub_list)))) + 1)
                    mr_np = sub_list * ranking_array
                    mr = 0.0
                    for team in mr_np:
                        if team > 0:
                            mr = team
                            break
                separate_result.append(mr)
            return (np.mean(separate_result), separate_result)

    @staticmethod
    def map(data):
        """
        Compute the MAP of the input data. MAP is the mean of average precision (AP).

        Parameters
        ----------
        data : tuple or list
            The data must be a tuple of the form ([0, 1, ...], ground_truth_num) or a list of such tuples.
            1 indicates a correct answer and 0 indicates an incorrect one.

        Returns
        -------
        tuple
            If `data` is a single tuple, returns (ap, [ap]).
            If `data` is a list of tuples, returns (mean_ap, [ap_1, ap_2, ...]).
        """
        if type(data) != list and type(data) != tuple:
            raise Exception('the input must be a tuple([0,...,1,...],int) or an iterable of list of tuple')
        if len(data) == 0:
            return (0.0, [0.0])
        if type(data) == tuple:
            sub_list, total_num = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return (0.0, [0.0])
            else:
                ranking_array = 1.0 / (np.array(list(range(len(sub_list)))) + 1)
                right_ranking_list = []
                count = 1
                for t in sub_list:
                    if t == 0:
                        right_ranking_list.append(0)
                    else:
                        right_ranking_list.append(count)
                        count += 1
                ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num
                return (ap, [ap])
        if type(data) == list:
            separate_result = []
            for sub_list, total_num in data:
                sub_list = np.array(sub_list)
                if total_num == 0:
                    ap = 0.0
                else:
