    @staticmethod
    def mrr(data):
        """
        Compute the Mean Reciprocal Rank (MRR) of the input data.

        Parameters
        ----------
        data : tuple or list of tuples
            Each element represents a query result. A tuple must be of the form
            (actual_results, ground_truth_total), where `actual_results` is a
            list/tuple of 0/1 values indicating incorrect/correct results, and
            `ground_truth_total` is the total number of relevant items for
            that query.

        Returns
        -------
        tuple
            A tuple containing:
            1. The average MRR over all queries (float).
            2. A list of individual MRR values for each query (list of float).
        """
        # Validate input type
        if type(data) not in (list, tuple):
            raise Exception(
                "the input must be a tuple([0,...,1,...],int) or an iteration of list of tuples"
            )

        # Empty list case
        if isinstance(data, list) and len(data) == 0:
            return (0.0, [0.0])

        # Single query (tuple)
        if isinstance(data, tuple):
            sub_list, total_num = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return (0.0, [0.0])

            ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
            mr_np = sub_list * ranking_array
            # first non-zero element gives the reciprocal rank
            mr = 0.0
            for val in mr_np:
                if val > 0:
                    mr = val
                    break
            return (mr, [mr])

        # Multiple queries (list of tuples)
        separate_result = []
        for sub_list, total_num in data:
            sub_list = np.array(sub_list)
            if total_num == 0:
                mr = 0.0
