class NumberConverter:
    """
    Provides conversion utilities between decimal, binary, octal, and hexadecimal representations.
    All methods are static and do not depend on instance state.
    """

    @staticmethod
    def decimal_to_binary(decimal_num: int) -> str:
        """
        Convert a decimal integer to its binary string representation.

        :param decimal_num: Integer in decimal base.
        :return: Binary string without the '0b' prefix.
        :raises ValueError: If ``decimal_num`` is not an integer.
        """
        if not isinstance(decimal_num, int):
            raise ValueError("Input must be an integer")
        return bin(decimal_num)[2:]

    @staticmethod
    def binary_to_decimal(binary_num: str) -> int:
        """
        Convert a binary string to its decimal integer representation.

        :param binary_num: Binary number as a string.
        :return: Decimal integer.
        :raises ValueError: If ``binary_num`` contains characters other than 0 or 1.
        """
        if not all(c in "01" for c in binary_num):
            raise ValueError("Input must be a binary string")
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num: int) -> str:
        """
        Convert a decimal integer to its octal string representation.

        :param decimal_num: Integer in decimal base.
        :return: Octal string without the '0o' prefix.
        """
        if not isinstance(decimal_num, int):
            raise ValueError("Input must be an integer")
        return oct(decimal_num)[2:]

    @staticmethod
    def octal_to_decimal(octal_num: str) -> int:
        """
        Convert an octal string to its decimal integer representation.

        :param octal_num: Octal number as a string.
        :return: Decimal integer.
        :raises ValueError: If ``octal_num`` contains invalid octal digits.
        """
        if not all(c in "01234567" for c in octal_num):
            raise ValueError("Input must be an octal string")
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num: int) -> str:
        """
        Convert a decimal integer to its hexadecimal string representation.

        :param decimal_num: Integer in decimal base.
        :return: Hexadecimal string in lowercase without the '0x' prefix.
        """
        if not isinstance(decimal_num, int):
            raise ValueError("Input must be an integer")
        return hex(decimal_num)[2:]

    @staticmethod
    def hex_to_decimal(hex_num: str) -> int:
        """
        Convert a hexadecimal string to its decimal integer representation.

        :param hex_num: Hexadecimal number as a string (case-insensitive).
        :return: Decimal integer.
        :raises ValueError: If ``hex_num`` contains invalid hexadecimal digits.
        """
        if not all(c in "0123456789abcdefABCDEF" for c in hex_num):
            raise ValueError("Input must be a hexadecimal string")
        return int(hex_num, 16)
