import re
from typing import Union


class NumberWordFormatter:
    """
    This class converts a numeric value into its English word representation,
    handling both integer and decimal parts, and using appropriate magnitude
    suffixes (thousand, million, billion, etc.).
    """

    def __init__(self):
        self.NUMBER = [
            "", "ONE", "TWO", "THREE", "FOUR", "FIVE",
            "SIX", "SEVEN", "EIGHT", "NINE"
        ]
        self.NUMBER_TEEN = [
            "TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN",
            "FIFTEEN", "SIXTEEN", "SEVENTEEN", "EIGHTEEN", "NINETEEN"
        ]
        self.NUMBER_TEN = [
            "TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY",
            "SIXTY", "SEVENTY", "EIGHTY", "NINETY"
        ]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = [
            "", "k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"
        ]

    # ----------------------------------------------------------------------
    # Public API
    # ----------------------------------------------------------------------
    def format(self, x: Union[int, float]) -> str:
        """
        Converts a numeric value into words.
        """
        if isinstance(x, str):
            return self.format_string(x)

        # Separate sign, integer and fractional parts
        sign = ""
        if x < 0:
            sign = "MINUS "
            x = -x

        int_part = int(x)
        frac_part = str(x).split(".")[1] if isinstance(x, float) else ""

        int_words = self._int_to_words(int_part)
        if not int_words:
            int_words = "ZERO"

        if frac_part:
            # Convert each decimal digit individually
            frac_words = " ".join(self.NUMBER[int(d)] for d in frac_part)
            return f"{sign}{int_words} POINT {frac_words}".strip()
        else:
            return f"{sign}{int_words} ONLY".strip()

    def format_string(self, x: str) -> str:
        """
        Converts a string representation of a number into words.
        """
        if not isinstance(x, str):
            raise ValueError("Input must be a string")

        # Remove commas, spaces and leading/trailing whitespace
        cleaned = re.sub(r"[,\s]+", "", x.strip())

        if not cleaned:
            raise ValueError("Empty string")

        try:
            # Try integer first, then float
            if "." in cleaned:
                num = float(cleaned)
            else:
                num = int(cleaned)
        except ValueError as exc:
            raise ValueError(f"Invalid numeric string: {x}") from exc

        return self.format(num)

    # ----------------------------------------------------------------------
    # Helper functions
    # ----------------------------------------------------------------------
    def trans_two(self, s: str) -> str:
        """
        Converts a two-digit string into words.
        """
        s = s.zfill(2)
        d1, d2 = int(s[0]), int(s[1])

        if d1 == 0:
            return self.NUMBER[d2]
        if d1 == 1:
            return self.NUMBER_TEEN[d2]
        tens_word = self.NUMBER_TEN[d1]
        if d2 == 0:
            return tens_word
        return f"{tens_word} {self.NUMBER[d2]}"

    def trans_three(self, s: str) -> str:
        """
        Converts a three-digit string into words.
        """
        s = s.zfill(3)
        h, t, u = int(s[0]), int(s[1]), int(s[2])

        if h == 0 and t == 0 and u == 0:
            return ""

        parts = []

        if h:
            parts.append(f"{self.NUMBER[h]} HUNDRED")
            if t or u:
                parts.append("AND")

        if t or u:
            parts.append(self.trans_two(s[1:]))

        return " ".join(parts)

    def parse_more(self, i: int) -> str:
        """
        Returns the magnitude suffix for a given group index.
        """
        if 0 <= i < len(self.NUMBER_MORE):
            return self.NUMBER_MORE[i]
        return ""

    def _int_to_words(self, number: int) -> str:
        """
        Internal helper to convert an integer into words.
        """
        if number == 0:
            return ""

        words = []
        group_index = 0

        while number > 0:
            group = number % 1000
            if group:
                group_word = self.trans_three(f"{group:03d}")
                suffix = self.parse_more(group_index)
                if suffix:
                    words.append(f"{group_word} {suffix}".strip())
                else:
                    words.append(group_word)
            number //= 1000
            group_index += 1

        return " ".join(reversed(words))
