class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'
        """
        out = []
        pos = 0
        length = len(string)
        while pos < length - 2:
            if string[pos] == '&' and string[pos + 1] == '#':
                start = pos + 2
                is_hex = False
                first_char = string[start]
                if first_char == 'x' or first_char == 'X':
                    start += 1
                    is_hex = True
                if start == length:
                    return ''.join(out)
                end = start
                while end < length and self.is_hex_char(string[end]):
                    end += 1
                if end < length and string[end] == ';':
                    try:
                        entity_value = int(string[start:end], 16 if is_hex else 10)
                    except Exception:
                        return ''.join(out)
                    out.append(chr(entity_value))
                    pos = end + 1
                    continue
            out.append(string[pos])
            pos += 1
        return ''.join(out)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True
        """
        return char.isdigit() or 'a' <= char.lower() <= 'f'

class PushBoxGame:
    """
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    """

    def __init__(self, map):
        """
        Initialize the push box game with the map and various attributes.
        :param map: list[str], the map of the push box game, represented as a list of strings.
            Each character on the map represents a different element, including the following:
            - '#' represents a wall that neither the player nor the box can pass through;
            - 'O' represents the initial position of the player;
            - 'G' represents the target position;
            - 'X' represents the initial position of the box.
        >>> map = ["#####", "#O  #", "# X #", "#  G#", "#####"]
        >>> game = PushBoxGame(map)
        """
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        """
        Initialize the game by setting the positions of the player, targets, and boxes based on the map.
        """
        for row in range(len(self.map)):
            for col in range(len(self.map[row])):
                char = self.map[row][col]
                if char == 'O':
                    self.player_row = row
                    self.player_col = col
                elif char == 'G':
                    self.targets.append((row, col))
                    self.target_count += 1
                elif char == 'X':
                    self.boxes.append((row, col))

    def check_win(self):
        """
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of self.is_game_over.
        :return self.is_game_over: True if all the boxes are placed on target positions, or False otherwise.
        """
        on_target = sum(1 for box in self.boxes if box in self.targets)
        if on_target == self.target_count:
            self.is_game_over = True
        else:
            self.is_game_over = False
        return self.is_game_over

    def move(self, direction):
        """
        Move the player based on the specified direction and check if the game is won.
        :param direction: str, the direction of the player's movement.
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.
        :return: True if the game is won, False otherwise.
        """
        delta_row, delta_col = 0, 0
        if direction == 'w':
            delta_row = -1
        elif direction == 's':
            delta_row = 1
        elif direction == 'a':
            delta_col = -1
        elif direction == 'd':
            delta_col = 1
        else:
            return self.is_game_over  # invalid direction, no move

        new_player_row = self.player_row + delta_row
        new_player_col = self.player_col + delta_col

        # Check bounds
        if not (0 <= new_player_row < len(self.map) and 0 <= new_player_col < len(self.map[0])):
            return self.is_game_over

        target_cell = self.map[new_player_row][new_player_col]

        # If wall, cannot move
        if target_cell == '#':
            return self.is_game_over

        # If there's a box, try to push it
        if (new_player_row, new_player_col) in self.boxes:
            new_box_row = new_player_row + delta_row
            new_box_col = new_player_col + delta_col

            # Check bounds for the box
            if not (0 <= new_box_row < len(self.map) and 0 <= new_box_col < len(self.map[0])):
                return self.is_game_over

            if self.map[new_box_row][new_box_col] == '#':
                return self.is_game_over
            if (new_box_row, new_box_col) in self.boxes:
                # Cannot push two boxes at once
                return self.is_game_over

            # Move box
            self.boxes.remove((new_player_row, new_player_col))
            self.boxes.append((new_box_row, new_box_col))

        # Move player
        self.player_row = new_player_row
        self.player_col = new_player_col

        return self.check_win()

    def print_map(self):
        """
        Prints the current state of the map to stdout.
        """
        for row in range(len(self.map)):
            row_chars = []
            for col in range(len(self.map[row])):
                if (row, col) == (self.player_row, self.player_col):
                    row_chars.append('O')
                elif (row, col) in self.boxes:
                    row_chars.append('X')
                elif (row, col) in self.targets:
                    row_chars.append('G')
                else:
                    row_chars.append(self.map[row][col])
            print(' '.join(row_chars))

