import math

class Statistics3:
    """
    This class implements basic statistical measures such as median, mode,
    mean, standard deviation, correlation, correlation matrix, and Z-score.
    """

    @staticmethod
    def median(data):
        """
        Calculates the median of the given list.
        """
        sorted_data = sorted(data)
        n = len(sorted_data)
        if n == 0:
            raise ValueError("Median requires at least one data point")
        if n % 2 == 1:
            return sorted_data[n // 2]
        else:
            return (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2

    @staticmethod
    def mode(data):
        """
        Calculates the mode of the given list.
        """
        if not data:
            return []
        counts = {}
        for value in data:
            counts[value] = counts.get(value, 0) + 1
        max_count = max(counts.values())
        return [value for value, count in counts.items() if count == max_count]

    @staticmethod
    def correlation(x, y):
        """
        Calculates the Pearson correlation coefficient of two lists.
        """
        if len(x) != len(y) or not x:
            raise ValueError("Lists must be of equal non-zero length")
        n = len(x)
        mean_x = sum(x) / n
        mean_y = sum(y) / n
        numerator = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
        denom_x = sum((xi - mean_x) ** 2 for xi in x)
