import random
import ast
from collections import Counter


class TwentyFourPointGame:
    """
    This is a game of twenty-four points, which provides to generate four numbers and check whether player's expression is equal to 24.
    """

    def __init__(self) -> None:
        self.nums = []

    def _generate_cards(self):
        """
        Generate random numbers between 1 and 9 for the cards.
        """
        self.nums = [random.randint(1, 9) for _ in range(4)]

    def get_my_cards(self):
        """
        Get a list of four random numbers between 1 and 9 representing the player's cards.
        :return: list of integers, representing the player's cards
        >>> game = TwentyFourPointGame()
        >>> game.get_my_cards()
        """
        self._generate_cards()
        return self.nums

    def answer(self, expression: str) -> bool:
        """
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: string, mathematical expression using the cards
        :return: bool, True if the expression evaluates to 24, False otherwise
        >>> game = TwentyFourPointGame()
        >>> game.nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.answer(ans)
        True
        """
        if not self.nums:
            return False

        try:
            expr_numbers = self._extract_numbers(expression)
        except Exception:
            return False

        # Ensure every number is used exactly as many times as it appears in self.nums
        if Counter(expr_numbers) != Counter(self.nums):
            return False

        return self.evaluate_expression(expression)

    def evaluate_expression(self, expression: str) -> bool:
        """
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: string, mathematical expression
        :return: bool, True if the expression evaluates to 24, False otherwise
        >>> game = TwentyFourPointGame()
        >>> nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.evaluate_expression(ans)
        True
        """
        try:
            tree = ast.parse(expression, mode="eval")
            result = self._eval_ast(tree.body)
            return abs(result - 24) < 1e-8
        except Exception:
            return False

    # ------------------------------------------------------------------
    # Internal helper methods
    # ------------------------------------------------------------------
    def _extract_numbers(self, expression: str):
        """
        Parse the expression and extract all integer constants.
        Raises ValueError if the expression contains invalid constants or values out of range.
        """
        tree = ast.parse(expression, mode="eval")
        numbers = []

        def _visit(node):
            if isinstance(node, ast.Constant):
                if isinstance(node.value, int):
                    if 1 <= node.value <= 9:
                        numbers.append(node.value)
                    else:
                        raise ValueError("Number out of allowed range")
                else:
                    raise ValueError("Non-integer constant")
            elif isinstance(node, ast.Num):  # Python < 3.8
                if isinstance(node.n, int):
                    if 1 <= node.n <= 9:
                        numbers.append(node.n)
                    else:
                        raise ValueError("Number out of allowed range")
                else:
                    raise ValueError("Non-integer constant")
            elif isinstance(node, (ast.BinOp, ast.UnaryOp)):
                for child in ast.iter_child_nodes(node):
                    _visit(child)
            else:
                raise ValueError("Unsupported expression component")

        _visit(tree.body)
        return numbers

    def _eval_ast(self, node):
        """
        Recursively evaluate an AST node.
        Supports +, -, *, / and unary +/-. Raises exception on invalid nodes or division by zero.
        """
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return node.value
            raise ValueError("Invalid constant type")

        if isinstance(node, ast.Num):  # Python < 3.8
            if isinstance(node.n, (int, float)):
                return node.n
            raise ValueError("Invalid number type")

        if isinstance(node, ast.BinOp):
            left = self._eval_ast(node.left)
            right = self._eval_ast(node.right)

            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            if isinstance(node.op, ast.Div):
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                return left / right
            raise ValueError("Unsupported binary operator")

        if isinstance(node, ast.UnaryOp):
            operand = self._eval_ast(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +operand
            if isinstance(node.op, ast.USub):
                return -operand
            raise ValueError("Unsupported unary operator")

        raise ValueError("Unsupported AST node")
