import math
from collections import Counter
from typing import List, Any

class Statistics3:
    """
    This is a class that implements methods for calculating indicators such as median, mode,
    correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def median(data: List[float]) -> float:
        """calculates the median of the given list."""
        n = len(data)
        if n == 0:
            raise ValueError("median requires at least one data point")
        sorted_data = sorted(data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0
        return float(sorted_data[mid])

    @staticmethod
    def mode(data: List[Any]) -> List[Any]:
        """calculates the mode of the given list."""
        if not data:
            return []
        counter = Counter(data)
        max_freq = max(counter.values())
        # If every value appears only once, there is technically no mode.
        if max_freq == 1:
            return []
        return [value for value, freq in counter.items() if freq == max_freq]

    @staticmethod
    def mean(data: List[float]) -> float:
        """calculates the mean of the given list."""
        if not data:
            raise ValueError("mean requires at least one data point")
        return sum(data) / len(data)

    @staticmethod
    def standard_deviation(data: List[float]) -> float:
        """calculates the standard deviation of the given list (sample standard deviation)."""
        n = len(data)
        if n < 2:
            return 0.0
        m = Statistics3.mean(data)
        variance = sum((x - m) ** 2 for x in data) / (n - 1)
        return math.sqrt(variance)

    @staticmethod
    def z_score(data: List[float]) -> List[float]:
        """calculates the z-score of the given list."""
        if not data:
            return []
        m = Statistics3.mean(data)
        sd = Statistics3.standard_deviation(data)
        if sd == 0:
            return [0.0 for _ in data]
        return [(x - m) / sd for x in data]

    @staticmethod
    def correlation(x: List[float], y: List[float]) -> float:
        """calculates the correlation of the given two lists."""
        if len(x) != len(y):
            raise ValueError("Lists x and y must have the same length")
        n = len(x)
        if n < 2:
            return 0.0
        mx = Statistics3.mean(x)
        my = Statistics3.mean(y)
        numerator = sum((xi - mx) * (yi - my) for xi, yi in zip(x, y))
        denom_x = sum((xi - mx) ** 2 for xi in x)
        denom_y = sum((yi - my) ** 2 for yi in y)
        denominator = math.sqrt(denom_x * denom_y)
        return numerator / denominator if denominator != 0 else 0.0

    @staticmethod
    def correlation_matrix(data: List[List[float]]) -> List[List[float]]:
        """
        calculates the correlation matrix of the given list.
        Each sub-list is treated as a variable's values across observations.
        """
        if not data:
            return []
        # Ensure all variables have the same length
        length = len(data[0])
        if any(len(var) != length for var in data):
            raise ValueError("All variables must have the same number of observations")
        size = len(data)
        matrix = [[0.0 for _ in range(size)] for _ in range(size)]
        for i in range(size):
            for j in range(i, size):
                corr = Statistics3.correlation(data[i], data[j])
                matrix[i][j] = corr
                matrix[j][i] = corr
        return matrix
