class Calculator:
    """
    Calculator capable of evaluating arithmetic expressions containing the operators
    +, -, *, /, ^ (exponentiation) and parentheses.
    """

    def __init__(self):
        """Initialize the operation functions for each supported operator."""
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y,
        }

    def calculate(self, expression: str):
        """
        Evaluate a mathematical expression given as a string.
        Supports +, -, *, /, ^ and parentheses.
        Returns the numeric result or None if the expression is empty or invalid.
        """
        if not expression:
            return None

        operand_stack = []
        operator_stack = []
        num_buffer = ""

        for char in expression:
            if char.isspace():
                continue

            if char.isdigit() or char == '.':
                num_buffer += char
                continue

            # Flush the number buffer
            if num_buffer:
                operand_stack.append(float(num_buffer))
                num_buffer = ""

            if char in self.operators:
                # Resolve operators with higher or equal precedence
                while (
                    operator_stack
                    and operator_stack[-1] != '('
                    and self.precedence(operator_stack[-1]) >= self.precedence(char)
                ):
                    operand_stack, operator_stack = self.apply_operator(
                        operand_stack, operator_stack
                    )
                operator_stack.append(char)

            elif char == '(':
                operator_stack.append(char)

            elif char == ')':
                # Pop operators until the matching '('
                while operator_stack and operator_stack[-1] != '(':
                    operand_stack, operator_stack = self.apply_operator(
                        operand_stack, operator_stack
                    )
                if operator_stack and operator_stack[-1] == '(':
                    operator_stack.pop()
                else:
                    # Mismatched parentheses
                    return None

            else:
                # Unsupported character
                return None

        # Flush any remaining number
        if num_buffer:
            operand_stack.append(float(num_buffer))

        # Apply any remaining operators
        while operator_stack:
            if operator_stack[-1] == '(' or operator_stack[-1] == ')':
                # Mismatched parentheses
                return None
            operand_stack, operator_stack = self.apply_operator(
                operand_stack, operator_stack
            )

        return operand_stack[-1] if operand_stack else None

    def precedence(self, operator: str) -> int:
        """
        Return the precedence value of an operator.
        Higher numbers mean higher precedence.
        """
        return {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}.get(operator, 0)

    def apply_operator(self, operand_stack: list, operator_stack: list):
        """
        Apply the operator at the top of the operator stack to the top two operands
        in the operand stack. Push the result back onto the operand stack.
        """
        if not operator_stack:
            return operand_stack, operator_stack

        operator = operator_stack.pop()

        if operator not in self.operators:
            # Unsupported operator
            return operand_stack, operator_stack

        if len(operand_stack) < 2:
            # Not enough operands
            return operand_stack, operator_stack

        operand2 = operand_stack.pop()
        operand1 = operand_stack.pop()
        result = self.operators[operator](operand1, operand2)
        operand_stack.append(result)

        return operand_stack, operator_stack
