class CamelCaseMap:
    """
    This is a custom class that allows keys to be in camel case style by converting them from underscore style,
    which provides dictionary-like functionality.
    """

    def __init__(self):
        """Initialize data to an empty dictionary."""
        self._data = {}

    def __getitem__(self, key):
        """Return the value corresponding to the key."""
        return self._data[self._convert_key(key)]

    def __setitem__(self, key, value):
        """Set the value corresponding to the key to the specified value."""
        self._data[self._convert_key(key)] = value

    def __delitem__(self, key):
        """Delete the value corresponding to the key."""
        del self._data[self._convert_key(key)]

    def __iter__(self):
        """Return an iterator over the keys of the internal dictionary."""
        return iter(self._data)

    def __len__(self):
        """Return the number of items stored."""
        return len(self._data)

    def _convert_key(self, key):
        """
        Convert a key string into camel case if it is a string.
        Non-string keys are returned unchanged.
        """
        if isinstance(key, str):
            return self._to_camel_case(key)
        return key

    @staticmethod
    def _to_camel_case(key):
        """
        Convert a snake_case string into camelCase.
        Example: 'first_name' -> 'firstName'.
        """
        if '_' not in key:
            return key  # already not snake_case
        parts = key.split('_')
        # first part stays as is, subsequent parts are title-cased and concatenated
        return parts[0] + ''.join(part.title() for part in parts[1:])
