class JobMarketplace:
    """
    This is a class that provides functionalities to publish positions, remove positions,
    submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    """

    def __init__(self):
        self.job_listings = []
        self.resumes = []

    def post_job(self, job_title, company, requirements):
        """
        Publishes a position and adds the position information to the job_listings list.
        """
        job = {
            "job_title": job_title,
            "company": company,
            "requirements": list(requirements)  # ensure a new list
        }
        self.job_listings.append(job)

    def remove_job(self, job):
        """
        Removes a position from the job_listings list.
        """
        try:
            self.job_listings.remove(job)
        except ValueError:
            pass  # ignore if job not in list

    def submit_resume(self, name, skills, experience):
        """
        Submits a resume and adds the resume information to the resumes list.
        """
        resume = {
            "name": name,
            "skills": list(skills),
            "experience": experience
        }
        self.resumes.append(resume)

    def withdraw_resume(self, resume):
        """
        Withdraws a resume and removes the resume information from the resumes list.
        """
        try:
            self.resumes.remove(resume)
        except ValueError:
            pass  # ignore if resume not in list

    def search_jobs(self, criteria):
        """
        Searches for positions that match the given criteria and returns the matching job listings.
        """
        return [
            job for job in self.job_listings
            if criteria in job.get("requirements", [])
        ]

    def _matches_requirements(self, job, resume):
        """
        Helper method to determine if a resume satisfies the job requirements.
        """
        job_reqs = set(job.get("requirements", []))
        resume_skills = set(resume.get("skills", []))
        return job_reqs.issubset(resume_skills)

    def get_job_applicants(self, job):
        """
        Obtains candidate information that meets the job requirements.
        """
        return [
            resume for resume in self.resumes
            if self._matches_requirements(job, resume)
        ]
