import numpy as np


class MetricsCalculator2:
    """
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data,
    where MRR measures the ranking quality and MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        Compute the MRR of the input data. MRR is the mean of reciprocal rank.
        :param data: a tuple ([0,1,…], ground_truth_num) or a list of such tuples.
        :return: (mrr_value, [mrr_value]) for a single tuple, or (mean_mrr, [mrr for each tuple]) for a list.
        """
        if not isinstance(data, (list, tuple)):
            raise Exception(
                "the input must be a tuple([0,...,1,...],int) or an iterable of list of tuples"
            )
        if len(data) == 0:
            return 0.0, [0.0]

        # single tuple case
        if isinstance(data, tuple):
            sub_list, total_num = data
            sub_arr = np.array(sub_list)
            if total_num == 0:
                return 0.0, [0.0]
            # Find first relevant item
            for idx, val in enumerate(sub_arr):
                if val != 0:
                    mr = 1.0 / (idx + 1)
                    return mr, [mr]
            return 0.0, [0.0]

        # list of tuples case
        results = []
        for sub_list, total_num in data:
            sub_arr = np.array(sub_list)
            if total_num == 0:
                mr = 0.0
            else:
                mr = 0.0
                for idx, val in enumerate(sub_arr):
                    if val != 0:
                        mr = 1.0 / (idx + 1)
                        break
            results.append(mr)
        return float(np.mean(results)), results

    @staticmethod
    def map(data):
        """
        Compute the MAP of the input data. MAP is the mean of average precision (AP).
        :param data: a tuple ([0,1,…], ground_truth_num) or a list of such tuples.
        :return: (map_value, [map_value]) for a single tuple, or (mean_map, [ap for each tuple]) for a list.
        """
        if not isinstance(data, (list, tuple)):
            raise Exception(
                "the input must be a tuple([0,...,1,...],int) or an iterable of list of tuples"
            )
        if len(data) == 0:
            return 0.0, [0.0]

        # helper to compute AP for one sub-list
        def _ap(sub_list, total_num):
            if total_num == 0:
                return 0.0
            sub_arr = np.array(sub_list)
            if total_num == 0:
                return 0.0
            # positions where we have relevant items
            relevant_positions = np.where(sub_arr == 1)[0]
            if len(relevant_positions) == 0:
                return 0.0
            # cumulative number of relevant items up to each position
            cum_rel = np.cumsum(sub_arr)
            precisions = cum_rel[relevant_positions] / (relevant_positions + 1)
            return float(np.sum(precisions) / total_num)

        # single tuple case
        if isinstance(data, tuple):
            sub_list, total_num = data
            ap = _ap(sub_list, total_num)
            return ap, [ap]

        # list of tuples case
        results = []
        for sub_list, total_num in data:
            ap = _ap(sub_list, total_num)
            results.append(ap)
        return float(np.mean(results)), results
