            return float(np.sum(precisions) / total_num)

        # single tuple case
        if isinstance(data, tuple):
            sub_list, total_num = data
            ap = _ap(sub_list, total_num)
            return ap, [ap]

        # list of tuples case
        results = []
        for sub_list, total_num in data:
            ap = _ap(sub_list, total_num)
            results.append(ap)
        return float(np.mean(results)), results

