class WeatherSystem:
    """
    This is a class representing a weather system that provides functionality to query weather information for a specific city and convert temperature units between Celsius and Fahrenheit.
    """

    def __init__(self, city: str) -> None:
        """
        Initialize the weather system with a city name.
        """
        self.temperature: float | None = None
        self.weather: str | None = None
        self.city: str = city
        self.weather_list: dict = {}

    def query(self, weather_list: dict, tmp_units: str = 'celsius') -> tuple[float, str]:
        """
        Query the weather system for the weather and temperature of the city,and convert the temperature units based on the input parameter.
        :param weather_list: a dictionary of weather information for different cities,dict.
        :param tmp_units: the temperature units to convert to, str.
        :return: the temperature and weather of the city, tuple.
        """
        if self.city not in weather_list:
            raise KeyError(f"Weather information for city '{self.city}' not found.")
        self.weather_list = weather_list
        data = weather_list[self.city]
        weather = data['weather']
        temp = data['temperature']
        units = data.get('temperature units', 'celsius')

        # Convert temperature if needed
        if units.lower() == tmp_units.lower():
            converted_temp = temp
        elif units.lower() == 'celsius' and tmp_units.lower() == 'fahrenheit':
            converted_temp = self._celsius_to_fahrenheit(temp)
        elif units.lower() == 'fahrenheit' and tmp_units.lower() == 'celsius':
            converted_temp = self._fahrenheit_to_celsius(temp)
        else:
            raise ValueError(f"Unsupported temperature unit conversion: {units} -> {tmp_units}")

        self.temperature = converted_temp
        self.weather = weather
        return (self.temperature, self.weather)

    def set_city(self, city: str) -> None:
        """
        Set the city of the weather system.
        :param city: the city to set, str.
        :return: None
        """
        self.city = city

    def celsius_to_fahrenheit(self) -> float:
        """
        Convert the temperature from Celsius to Fahrenheit.
        :return: the temperature in Fahrenheit, float.
        """
        if self.temperature is None:
            raise ValueError("Temperature is not set.")
        return self._celsius_to_fahrenheit(self.temperature)

    def fahrenheit_to_celsius(self) -> float:
        """
        Convert the temperature from Fahrenheit to Celsius.
        :return: the temperature in Celsius, float.
        """
        if self.temperature is None:
            raise ValueError("Temperature is not set.")
        return self._fahrenheit_to_celsius(self.temperature)

    @staticmethod
    def _celsius_to_fahrenheit(celsius: float) -> float:
        return celsius * 9 / 5 + 32

    @staticmethod
    def _fahrenheit_to_celsius(fahrenheit: float) -> float:
        return (fahrenheit - 32) * 5 / 9
