class MetricsCalculator2:
    """
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP)
    based on input data. MRR measures the ranking quality and MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        Compute the MRR of the input data. MRR is the mean of reciprocal ranks.
        :param data: a tuple or a list of tuples.
            Each tuple is (actual_result, ground_truth_num), where actual_result is a list
            of 0/1 values and ground_truth_num is the total number of relevant items.
        :return: a tuple (mean_mrr, [mrr_for_each_item]).
        """
        if not isinstance(data, (list, tuple)):
            raise Exception(
                'the input must be a tuple([0,...,1,...],int) or an iteration of list of tuples'
            )

        if len(data) == 0:
            return (0.0, [0.0])

