import re
from typing import Pattern


class NumericEntityUnescaper:
    """
    Provides functionality to replace numeric entities (HTML numeric character references)
    with their corresponding Unicode characters in a given string.
    """

    def __init__(self):
        # Patterns for decimal and hexadecimal numeric references
        self._decimal_re: Pattern[str] = re.compile(r'&#(\d+);')
        self._hex_re: Pattern[str] = re.compile(r'&#x([0-9a-fA-F]+);')

    def replace(self, string: str) -> str:
        """
        Replaces numeric character references (HTML entities) in the input string with
        their corresponding Unicode characters.

        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced.
        """
        def _replace_decimal(match: re.Match) -> str:
            number = match.group(1)
            try:
                codepoint = int(number)
                return chr(codepoint)
            except (ValueError, OverflowError):
                # If conversion fails, keep the original text
                return match.group(0)

        def _replace_hex(match: re.Match) -> str:
            number = match.group(1)
            try:
                codepoint = int(number, 16)
                return chr(codepoint)
            except (ValueError, OverflowError):
                return match.group(0)

        # Replace hex references first to avoid interference with decimal pattern
        result = self._hex_re.sub(_replace_hex, string)
        result = self._decimal_re.sub(_replace_decimal, result)
        return result

    @staticmethod
    def is_hex_char(char: str) -> bool:
        """
        Determines whether a given character is a hexadecimal digit.

        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        """
        if len(char) != 1:
            return False
        return char.lower() in '0123456789abcdef'
