import math
from collections import Counter
from typing import List, Any


class Statistics3:
    """
    Implements basic statistical indicators: median, mode, correlation, mean,
    correlation matrix, standard deviation, and z‑score.
    """

    @staticmethod
    def median(data: List[float]) -> float:
        """Return the median of *data*."""
        if not data:
            raise ValueError("median requires at least one data point")
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0
        return float(sorted_data[mid])

    @staticmethod
    def mode(data: List[float]) -> List[float]:
        """Return all modes of *data* as a list."""
        if not data:
            return []
        counter = Counter(data)
        max_freq = max(counter.values())
        return sorted([k for k, v in counter.items() if v == max_freq])

    @staticmethod
    def mean(data: List[float]) -> float:
        """Return the arithmetic mean of *data*."""
        if not data:
            raise ValueError("mean requires at least one data point")
        return sum(data) / len(data)

    @staticmethod
    def standard_deviation(data: List[float]) -> float:
        """Return the sample standard deviation of *data*."""
        n = len(data)
        if n < 2:
            raise ValueError("standard deviation requires at least two data points")
        m = Statistics3.mean(data)
        variance = sum((x - m) ** 2 for x in data) / (n - 1)
        return math.sqrt(variance)

    @staticmethod
    def correlation(x: List[float], y: List[float]) -> float:
        """Return the Pearson correlation coefficient of *x* and *y*."""
        if len(x) != len(y):
            raise ValueError("x and y must have the same length")
        n = len(x)
        if n == 0:
            raise ValueError("correlation requires at least one data point")
        mean_x = Statistics3.mean(x)
        mean_y = Statistics3.mean(y)
        std_x = Statistics3.standard_deviation(x)
        std_y = Statistics3.standard_deviation(y)
        if std_x == 0 or std_y == 0:
            return 0.0
        cov = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n)) / (n - 1)
        return cov / (std_x * std_y)

    @staticmethod
    def correlation_matrix(data: List[List[float]]) -> List[List[float]]:
        """Return the correlation matrix for a list of variables."""
        if not data:
            return []
        n = len(data)
        # Validate that each variable has the same length
        length = len(data[0])
        if any(len(v) != length for v in data):
            raise ValueError("All variables must have the same number of observations")
        matrix = [
            [Statistics3.correlation(data[i], data[j]) for j in range(n)]
            for i in range(n)
        ]
        return matrix

    @staticmethod
    def z_score(data: List[float]) -> List[float]:
        """Return the z‑score of each element in *data*."""
        if not data:
            return []
        mean_val = Statistics3.mean(data)
        std_val = Statistics3.standard_deviation(data)
        if std_val == 0:
            return [0.0] * len(data)
        return [(x - mean_val) / std_val for x in data]
