        """
        Get a list of four random numbers between 1 and 9 representing the player's cards.
        :return: list of integers, representing the player's cards
        """
        self._generate_cards()
        return self.nums

    def answer(self, expression: str) -> bool:
        """
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: string, mathematical expression using the cards
        :return: bool, True if the expression evaluates to 24, False otherwise
        """
        # If the player chooses to skip, provide a new set of cards.
        if expression == 'pass':
            return self.get_my_cards()

        # Count how many times each digit appears in the expression.
        digit_usage = {}
        for ch in expression:
            if ch.isdigit():
                digit = int(ch)
                if digit in self.nums:
                    digit_usage[ch] = digit_usage.get(ch, 0) + 1

        # Verify that each card number is used the appropriate number of times.
        remaining = {str(n): self.nums.count(n) for n in set(self.nums)}
        for ch, used in digit_usage.items():
            if remaining.get(ch, 0) >= used:
                remaining[ch] -= used
            else:
                return False

        # Ensure all cards have been used.
        if any(count != 0 for count in remaining.values()):
            return False

        return self.evaluate_expression(expression)

    def evaluate_expression(self, expression: str) -> bool:
        """
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: string, mathematical expression
        :return: bool, True if the expression evaluates to 24, False otherwise
        """
        try:
            return eval(expression) == 24
        except Exception:
            return False

